void dei_prk_output( Boolean status )
{    
    static Boolean last_status  = FALSE ; 
    static Boolean dome_status  = FALSE ; 

    if( last_status != status )
    {
        cmd_q_rs_insert( ((status)?INPUT_PARKING_ON:INPUT_PARKING_OFF) , 200 , 0 ) ; 

        if( dei_prk_dome_active )
		{
			cmd_q_rs_insert(((status)?INPUT_DOME_ON:INPUT_DOME_OFF) , 200 , 0 ) ; 
		
			dome_status = status ; 
		}			

		if( dome_status  && !status )
		{
			cmd_q_rs_insert( INPUT_DOME_OFF , 200 , 0 ) ; 					//complete the pattern for domelight

			dome_status = FALSE ;
		}

		
		
		
		if( !status )
        {
            ATOMIC( dei_prk_offset_length = 0 );
        };

        last_status = status ;
    }
}

